from pydantic import BaseModel, Field, ConfigDict
from typing import Optional, List, Dict, Any, Literal

class UserInfo(BaseModel):
    userEmail: str
    userName: str

class SlackInfo(BaseModel):
    slackUserId: Optional[str] = None
    slackThreadId: Optional[str] = None
    slackMessageId: Optional[str] = None
    slackChannelId: Optional[str] = None

class Feedback(BaseModel):
    option: str
    comment: Optional[str] = None

class FeedbackRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    conversationId: str = Field(alias="conversationID")
    messageId: str = Field(alias="messageID")
    feedback: Feedback

class FeedbackResponse(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    conversationId: str = Field(alias="conversationID")
    messageId: str = Field(alias="messageID")
    otherLinks: Dict[str, str]
    informationSaved: str

class Conversation(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    conversationId: str = Field(alias="conversationID")
    title: str
    platform: Optional[str]
    threadTs: Optional[str]
    channelId: Optional[str]

class ConversationRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    conversationId: Optional[str] = Field(None, alias="conversationID",
                                          description="Optional ID of an existing conversation. If omitted, a new conversation is started.")
    messageId: Optional[str] = Field(None, alias="messageID")
    userInfo: Optional[UserInfo] = Field(None, description="User name and email")
    slackInfo: Optional[SlackInfo] = None
    new_conversation: Optional[bool] = Field(None, alias="newConversation")
    timestamp: Optional[str] = None
    platform: Optional[str] = Field(None, description="request originated from")
    question: str
    feedback: Optional[Feedback] = None
    token: Optional[str] = None
    authTokens: Optional[Dict[str, str]] = None
class ImageReference(BaseModel):
    """Image reference from RAG retrieval (ServiceNow KB articles).

    This model represents an image reference from the knowledge base,
    containing the S3 pre-signed URL, filename, and image metadata.
    Used for displaying images inline in RAG responses.
    """

    filename: str = Field(
        description="The original filename of the image.",
        examples=["image_002.png", "workflow_diagram.jpg"],
    )
    url: str = Field(
        description="The S3 pre-signed URL for accessing the image (expires in 7 days).",
        examples=[
            "https://digital-workforce.s3.amazonaws.com/agents/tech-sales-agent/dev/servicenow-kb-sales/article_2/image_002.png?X-Amz-Algorithm=..."
        ],
    )
    image_index: int = Field(
        description="The index of this image within the source article.",
        examples=[1, 2, 3],
    )
    article_title: str = Field(
        description="The title of the article this image belongs to.",
        examples=["Credit Tax on Invoice", "Creating a Sales Quote"],
    )
    article_id: str = Field(
        description="The ServiceNow article ID.",
        examples=["2", "15", "42"],
    )
    description: str | None = Field(
        description="Optional description of the image content (generated by Gemini Vision).",
        default=None,
        examples=[
            "The image shows a ServiceNow form with fields for Credit Type, Amount, and Tax Code."
        ],
    )


class Response(BaseModel):
    answer: str
    sources: Dict[str, str] = Field(default_factory=dict)
    images: List[ImageReference] = Field(
        default_factory=list,
        description="List of images referenced in the response from RAG retrieval"
    )

class ConversationResponse(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    conversationId: str = Field(alias="conversationID")
    messageId: str = Field(alias="messageID")
    response: Response
    informationSaved: str
    chunkId: int
    streamEnded: bool
    otherLinks: Dict[str, str]

class ConversationMessage(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    comment: Optional[str]
    content: str
    conversationId: str = Field(alias="conversationID")
    reaction: Optional[bool]
    type: str
    images: Optional[List[ImageReference]] = Field(
        default_factory=list,
        description="List of images referenced in this message"
    )

class StreamChunk(BaseModel):
    """A single text chunk in a streaming response."""
    type: str = Field("chunk", description="Indicates a text chunk.")
    contentType: str = Field(description="Indicates the type of message content e.g. tool, ai, user, custom etc.")
    text: str = Field(..., description="A partial piece of the model's response text.")

class StreamEnd(BaseModel):
    """Indicates the end of a streaming response."""
    model_config = ConfigDict(populate_by_name=True)
    type: str = Field(description="Indicates the type of message e.g. message, chunk etc.")
    contentType: str = Field(description="Indicates the type of message content e.g. tool, ai, user, custom etc.")
    conversationId: str = Field(alias="conversationID", description="The ID of the conversation.")
    messageId: str = Field(alias="messageID", description="The ID of the final generated model message.")
    final_text: str = Field(None, alias="finalText", description="The complete text of the model's response.")
    timestamp: str = Field(None, description="ISO 8601 timestamp of the final message generation.")
    messageReferenceList: Optional[List[Dict[str, str]]] = Field(default=None, description="List of message references with label and url")
    imageReferenceList: Optional[List[ImageReference]] = Field(
        default=None,
        description="List of images referenced in the response from RAG retrieval"
    )

# Auth-related models
class AuthConfig(BaseModel):
    """Configuration for JWT authentication."""
    enabled: bool = Field(default=False, description="Whether authentication is enabled")
    issuer: str = Field(..., description="JWT issuer URL (e.g., https://accounts.google.com)")
    audience: str = Field(..., description="JWT audience")
    jwks_url: str = Field(..., description="JWKS URL for key validation")
    algorithms: List[str] = Field(default=["RS256"], description="Allowed JWT signing algorithms")
    verify_exp: bool = Field(default=True, description="Whether to verify token expiration")
    verify_aud: bool = Field(default=True, description="Whether to verify audience")

class UserContext(BaseModel):
    """User context extracted from JWT token."""
    sub: str = Field(..., description="Subject (user ID)")
    email: Optional[str] = Field(None, description="User email")
    name: Optional[str] = Field(None, description="User name")
    preferred_username: Optional[str] = Field(None, description="Preferred username")
    groups: Optional[List[str]] = Field(default_factory=list, description="User groups/roles")
    raw_token: Optional[Dict[str, Any]] = Field(None, description="Raw JWT token claims")

class CustomAuthHeaders(BaseModel):
    """
    Container for authentication headers from request.

    Extracts:
    1. Authorization bearer token from "Authorization: Bearer <token>" header
    2. All X-Authorization-* headers for third-party services

    Example:
        Headers:
            Authorization: Bearer eyJhbGciOiJSUzI1NiIsIn...
            X-Authorization-Snowflake: sk_live_abc123
            X-Authorization-PeopleAI: pk_abc123

        Results in:
            bearer_token = "eyJhbGciOiJSUzI1NiIsIn..."
            auth_tokens = {
                "Snowflake": "sk_live_abc123",
                "PeopleAI": "pk_abc123"
            }
    """
    bearer_token: Optional[str] = Field(
        default=None,
        description="JWT bearer token from Authorization header"
    )
    auth_tokens: Dict[str, str] = Field(
        default_factory=dict,
        description="Dictionary of service names to authentication tokens from X-Authorization-* headers"
    )

    def get(self, service_name: str) -> Optional[str]:
        """Get auth token for a specific service (case-insensitive)."""
        # Support case-insensitive lookup
        for key, value in self.auth_tokens.items():
            if key.lower() == service_name.lower():
                return value
        return None

    def has(self, service_name: str) -> bool:
        """Check if auth token exists for a service (case-insensitive)."""
        return self.get(service_name) is not None

    def __bool__(self) -> bool:
        """Return True if any auth tokens or bearer token are present."""
        return bool(self.auth_tokens) or bool(self.bearer_token)

class ToolCall(BaseModel):
    """Represents a request to call a tool."""
    name: str = Field(..., description="The name of the tool to be called")
    args: Dict[str, Any] = Field(..., description="The arguments to pass to the tool call")
    id: Optional[str] = Field(None, description="An optional identifier associated with the tool call")
    type: Optional[str] = Field("tool_call", description="The type identifier for tool calls")

class Source(BaseModel):
    """Source information from RAG retrieval."""
    label: str = Field(..., description="The section name or title of the source document")
    url: str = Field(..., description="The page URL of the source document")